export type Box<T> = { value: T };
export interface Item { value: string }
export type Select<T> = T extends string ? { text: T } : { count: number };
export type Copy<T> = { [K in keyof T]: T[K] };
export interface Left { left: string }
export interface Right { right: number }
import { primitive } from "./primitive";
export declare const genericAlias: Box<string>;
export declare const interfaceValue: Item;
export declare const conditionalValue: Select<string>;
export declare const mappedValue: Copy<Item>;
export declare const indexedValue: Item["value"];
export declare const intersectionValue: Left & Right;
export declare const typeofValue: typeof primitive;
export declare const firstDuplicate: Box<string>;
export declare const secondDuplicate: Box<string>;
export type Broken<T> = Missing<T>;
export declare const brokenString: Broken<string>;
export declare const brokenNumber: Broken<number>;
